            return True
        for l in range(27):
            if used_labels[l]:
                continue
            ok = True
            for prev in range(v):
                if (prev, v) in edge_set or (v, prev) in edge_set:  # if connected
                    d = abs(assignment[prev] - l)
                    if d == 0 or d > 26 or used_diffs[d]:
                        ok = False
                        break
            if ok:
                assignment[v] = l
                used_labels[l] = True
                marked = []
                for prev in range(v):
                    if (prev, v) in edge_set or (v, prev) in edge_set:
                        d = abs(assignment[prev] - l)
                        used_diffs[d] = True
                        marked.append(d)
                if bt(v+1):
