        for l in range(27):
            if used_labels[l]:
                continue
            # collect new diffs
            new_diffs = []
            ok = True
            seen_this = set()
            for prev in range(v):
                if (prev, v) in edge_set or (v, prev) in edge_set:
                    d = abs(assignment[prev] - l)
                    if d < 1 or d > 26 or used_diffs[d] or d in seen_this:
