                used_labels[l] = True
                for d in new_diffs:
                    used_diffs[d] = True
                if bt(v + 1):
                    return True
                for d in new_diffs:
                    used_diffs[d] = False
                used_labels[l] = False
        return False
    if bt(0):
        return assignment
    else:
