    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * 20
    def bt(v):
        if v == 20: return True
        used = 0
        for nei in adj[v]:
            if color[nei] != -1:
                used |= (1 << color[nei])
        for c in range(3):
            if (used & (1 << c)) == 0:
