from collections import defaultdict, deque

def is_valid_graph(edges, n=26):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    degrees = [len(adj[i]) for i in range(n)]
    if any(d < 3 or d > 4 for d in degrees):
        return False
