def girth(graph, n=26):
    min_cycle = float('inf')
    for start in range(n):
        queue = deque([(start, -1, 0)])  # node, parent, dist
        dist = [-1] * n
        dist[start] = 0
        while queue:
            node, parent, d = queue.popleft()
            for nei in graph[node]:
                if nei == parent:
                    continue
                if dist[nei] == -1:
                    dist[nei] = d + 1
                    queue.append((nei, node, d + 1))
                elif dist[nei] >= 0:
                    cycle = d + dist[nei] + 1
                    if cycle < min_cycle:
                        min_cycle = cycle
                        if min_cycle < 7:
                            return min_cycle
    return min_cycle

def generate_random_regular(n=26, degree=3, max_tries=1000):
    for try_num in range(max_tries):
        # Configuration model
        stubs = list(itertools.chain.from_iterable([ [i]*degree for i in range(n)]))
        random.shuffle(stubs)
        edges = []
        used = set()
        valid = True
        i = 0
        while i < len(stubs) - 1:
            u = stubs[i]
            v = stubs[i+1]
            if u > v:
                u, v = v, u
            if u == v or (u, v) in used:
                valid = False
                break
            edges.append((u, v))
            used.add((u, v))
            i += 2
        if not valid or len(edges) != (n * degree // 2):
            continue
        # check degrees exactly degree
        adj = defaultdict(list)
        for u,v in edges:
            adj[u].append(v)
            adj[v].append(u)
        if any(len(adj[i]) != degree for i in range(n)):
            continue
        g = girth(adj, n)
        if g >= 7:
            return sorted(edges), g
    return None, None

