import random
from collections import deque, defaultdict

def bfs_dist(graph, start, target, n):
    if start == target:
        return 0
    dist = [-1] * n
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                if v == target:
                    return dist[v]
                q.append(v)
    return float('inf')

def build_graph(n=24, target_edges=33):
    possible_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(possible_edges)
    graph = defaultdict(list)
    edges = []
    for u, v in possible_edges:
        d = bfs_dist(graph, u, v, n)
        if d >= 6:
            graph[u].append(v)
            graph[v].append(u)
            edges.append((u, v))
            if len(edges) >= target_edges:
                return edges
    return edges

