def is_colorable(edges, k):
    adj = [[] for _ in range(14)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * 14
    def bt(v):
        if v == 14:
            return True
        used = set(color[nei] for nei in adj[v] if color[nei] != -1)
        for c in range(k):
            if c not in used:
                color[v] = c
                if bt(v + 1):
                    return True
                color[v] = -1
        return False
    return bt(0)

