from collections import deque

def shortest_path_dist(adj, u, v, max_d=5):
    if u == v: return 0
    n = len(adj)
    dist = [-1] * n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_d:
            continue
        for y in adj[x]:
            if dist[y] == -1:
                dist[y] = dist[x] + 1
                if y == v:
                    return dist[y]
                q.append(y)
    return dist[v] if dist[v] != -1 else 999

